const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}static object Call(MultiSaveSystem s,string method,params object[] args)=>typeof(MultiSaveSystem).GetMethod(method,F).Invoke(s,args);static MultiSaveSystem.State State(MultiSaveSystem s)=>(MultiSaveSystem.State)typeof(MultiSaveSystem).GetField("state",F).GetValue(s);static void Tick(MultiSaveSystem s){UnityEngine.Time.realtimeSinceStartup+=1;Call(s,"OnUpdate");}static Game.UI.Editor.EditorHierarchyUISystem.HierarchyItem Row(int id,Game.UI.Editor.EditorHierarchyUISystem.ItemType kind=Game.UI.Editor.EditorHierarchyUISystem.ItemType.Object)=>new(){id=new(){prefab=id,type=kind}};
static (MultiSaveSystem,Game.UI.Editor.EditorHierarchyUISystem,Game.UI.Editor.InspectorPanelSystem,Game.Prefabs.PrefabSystem) Setup(){var s=new MultiSaveSystem();var h=new Game.UI.Editor.EditorHierarchyUISystem();var i=new Game.UI.Editor.InspectorPanelSystem();var p=new Game.Prefabs.PrefabSystem();s.World.Systems[typeof(Game.UI.Editor.EditorHierarchyUISystem)]=h;s.World.Systems[typeof(Game.UI.Editor.InspectorPanelSystem)]=i;s.World.Systems[typeof(Game.Prefabs.PrefabSystem)]=p;Call(s,"OnCreate");Game.SceneFlow.GameManager.instance.gameMode=Game.GameMode.Editor;Colossal.IO.AssetDatabase.AssetDatabase.user.Paths.Clear();return(s,h,i,p);}
static void Main(){
var(s,h,i,p)=Setup();p.Items[1]=new(){name="One",asset=new()};p.Items[2]=new(){name="Two",asset=new()};p.Items[3]=new(){name="Locked",isReadOnly=true};h.Rows(Row(1),Row(1),Row(2,Game.UI.Editor.EditorHierarchyUISystem.ItemType.Prefab),Row(3),Row(2,Game.UI.Editor.EditorHierarchyUISystem.ItemType.Mesh));Call(s,"Command","open");Tick(s);Check(State(s).eligible==2&&State(s).locked==1,"Whole hierarchy deduplicates assets and excludes locks/mesh dependencies");s.BlockReason=()=>"Recovery active";Call(s,"Command","saveAll");Check(!State(s).busy&&i.Saves.Count==0&&State(s).status=="Recovery active","Recovery interlock refuses start without a write");s.BlockReason=null;Call(s,"Command","saveAll");Tick(s);Check(i.Saves.Count==1&&State(s).busy,"Only first save dispatched");Tick(s);Check(i.Saves.Count==1,"Outstanding native dialog prevents overlapping save");Call(s,"Command","close");Check(State(s).busy&&!State(s).visible,"Changing tab/closing content preserves batch");i.Replies[0](new());Tick(s);Check(i.Saves.Count==2&&State(s).saved==1,"Next asset waits for first callback");i.Replies[1](new());Tick(s);Check(!State(s).busy&&State(s).saved==2&&State(s).processed==2,"Both unique assets finish");
Call(s,"Command","saveAll");Tick(s);var late=i.Replies[2];Call(s,"Command","stop");Tick(s);Check(State(s).busy&&i.Saves.Count==3,"Stop waits for current native callback");late(new());Tick(s);Check(!State(s).busy&&State(s).saved==1&&i.Saves.Count==3,"Stop leaves next asset unsaved");
Call(s,"Command","saveAll");Tick(s);var stale=i.Replies[3];Call(s,"OnStopRunning");var count=State(s).processed;stale(new());Check(!State(s).busy&&State(s).processed==count,"Editor stop invalidates delayed native callbacks");
var(s2,h2,i2,p2)=Setup();p2.Items[1]=new(){name="Conflict"};h2.Rows(Row(1));Colossal.IO.AssetDatabase.AssetDatabase.user.Paths.Add("Conflict");Call(s2,"Command","saveAll");Tick(s2);Check(i2.Saves.Count==0&&State(s2).failed==1,"New asset name collision never dispatches native overwrite");Tick(s2);Check(!State(s2).busy&&State(s2).processed==1,"Name conflict ends batch with failure count");
var(s3,h3,i3,p3)=Setup();p3.Items[1]=new(){name="Removed",asset=new()};h3.Rows(Row(1));Call(s3,"Command","saveAll");h3.Rows();Tick(s3);Check(i3.Saves.Count==0&&State(s3).skipped==1,"Asset removed before turn is skipped");h3.Rows(Row(1));Call(s3,"Command","saveAll");p3.Items[1].isReadOnly=true;Tick(s3);Check(i3.Saves.Count==0&&State(s3).skipped==1,"Asset locked before turn is skipped");
var(s4,h4,i4,p4)=Setup();p4.Items[1]=new(){name="New unique"};h4.Rows(Row(1));Call(s4,"Command","saveAll");Tick(s4);Check(i4.Saves.Count==1,"Unique unsaved asset uses native first-save path");i4.Replies[0](null);Tick(s4);Check(State(s4).failed==1&&!State(s4).busy,"Native failure callback reported and batch completes");s4.Release();Check(!State(s4).available&&!State(s4).busy,"Release resets availability and queue");
Console.WriteLine("PASS: "+checks+" actual-source Multi-Save queue/interlock checks with managed native-save stubs; no files saved.");
}
